  "style_constraints": {
    "no_text": true,
    "no_lines": true,
    "no_arrows": true,
    "no_watermarks": true,
    "no_over_smoothing": true,
    "no_beauty_filters": true,
    "no_identity_change": true,
    "no_exaggerated_filler": true
  }
}

