ぜひ試してみてね🥰
{
  "target": "NanoBanana",
  "role_task": "Create a professional OOTD magazine-style fashion collage",
  "layout": {
    "left": {
      "width_ratio": 0.6,
      "preserve": {
        "face": true,
        "hairstyle": true,
        "outfit": true
      },
      "photo_style": "clean, bright, magazine-quality",
      "pose": "cute, amusing, slightly quirky, realistic atmosphere"
    },
    "right": {
      "width_ratio": 0.4,
      "background": "white",
      "product_grid": {
        "quantity": "[quantity]",
        "arrangement": "vertical",
        "final_module": "underwear_estimated_from_image",
        "module_fields": [
          "product_image_cutout_white_bg",
          "product_name",
          "price_yen"
        ]
      }
    }
  },
  "example_products": [
    {
      "id": 1,
      "name": "[Product 1]",
      "price": "¥[price]",
      "image": "[path_or_url_or_placeholder]"
    },
    {
      "id": 2,
      "name": "[Product 2]",
      "price": "¥[price]",
      "image": "[path_or_url_or_placeholder]"
    },
    {
      "id": 3,
      "name": "[Product 3]",
      "price": "¥[price]",
      "image": "[path_or_url_or_placeholder]"
    },
    {
      "id": 4,
